import { Node, Group, Base, Port, Edge, Vertex } from './model/graph';
import { EdgeAddedParams, EdgeRemovedParams, EdgeSourceChangedParams, EdgeTargetChangedParams, GroupAddedParams, GroupMemberAddedParams, GroupMemberRemovedParams, GroupRemovedParams, NodeAddedParams, NodeRemovedParams, PortAddedParams, PortRemovedParams, VertexUpdatedParams } from "./params";
import { VisuallyJsSelection } from "./selection";
/**
 * Definition of a gradient - an array of [offset, color] entries.
 * @group UI
 * @category Definitions
 */
export type GradientSpec = Array<[number, string]>;
/**
 * Definition of an object that can render an instance of {@link VisuallyJsModel}. This interface is not something a user of the API needs to be concerned with, unless you are creating your own renderer type.
 * @internal
 */
export interface VisuallyJsRenderer<E, EVT = any> {
    id: string;
    bind(evt: EVT, payload: any): void;
    onDestroy(cb: (r: VisuallyJsRenderer<E>) => any): void;
    /**
     * Sets the position of some vertex and updates the model. This method will honour any grid that is currently in effect.
     */
    setPosition(vertex: Node | Group | E, x: number, y: number): void;
    setSuspendRendering(v: boolean, thenRefresh?: boolean): void;
    expandGroup(group: Group): void;
    collapseGroup(group: Group): void;
    $nodeAdded(p: NodeAddedParams): void;
    $groupAdded(p: GroupAddedParams): void;
    $edgeAdded(data: EdgeAddedParams, context?: Record<string, any>): void;
    $portAdded(p: PortAddedParams): void;
    $nodeRemoved(node: NodeRemovedParams): void;
    $groupRemoved(group: GroupRemovedParams): void;
    $edgeRemoved(data: EdgeRemovedParams): void;
    $portRemoved(data: PortRemovedParams): void;
    /**
     * export the geometry for some edge. Used by the model when the geometry is set on an
     * edge that does not currently have a geometry object.
     * @param edge
     * @internal
     */
    $exportEdgeGeometry(edge: Edge): any;
    $edgeGeometryUpdated(edge: Edge, geometry: any, originalGeometry: any): void;
    $nodeTypeChanged(node: Node, previousType: string, newType: string): void;
    $groupTypeChanged(group: Group, previousType: string, newType: string): void;
    $edgeTypeChanged(edge: Edge, previousType: string, newType: string): void;
    $portTypeChanged(port: Port, previousType: string, newType: string): void;
    $groupMemberAdded(p: GroupMemberAddedParams): void;
    $groupMemberRemoved(p: GroupMemberRemovedParams): void;
    $vertexUpdated(p: VertexUpdatedParams): void;
    $graphClearStart(): void;
    $graphClearEnd(): void;
    $edgeSourceChanged(params: EdgeSourceChangedParams): void;
    $edgeTargetChanged(params: EdgeTargetChangedParams): void;
    $select(payload: {
        obj: Base;
        selection: VisuallyJsSelection;
    }): void;
    $deselect(payload: {
        selection: VisuallyJsSelection;
        obj: Base;
    }): void;
    $selectionCleared(sel: VisuallyJsSelection): any;
    $dataLoadStart(): any;
    $dataAppendStart(): any;
    $dataLoadEnd(): any;
    $dataAppendEnd(): any;
    $renderDummyVertex(v: Vertex): void;
}
/**
 * A lightweight interface for UIs to respond to interactivity events
 * propagated by the model.
 * @group Model
 * @internal
 */
export interface UIObserver {
    onHover?: (source: UIObserver, obj: Base, state: boolean) => void;
    onSelect?: (source: UIObserver, obj: Base, state: boolean) => void;
    onTap?: (source: UIObserver, obj: Base, event: MouseEvent) => void;
}
